function hexPreview(text) {
  const cleaned = text.replace(/[^0-9a-f]/gi, '');
  return Array.from(Buffer.from(cleaned.length % 2 ? cleaned + '0' : cleaned, 'hex'));
}
module.exports = { hexPreview };

