const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/hex-preview.cjs');
test('hex decoder stops instead of repairing input', () => {
  for (const [text,expected] of [
    ['a2f104',[162,241,4]], ['a2g104',[162]], ['a2f',[162]],
    ['g1a2',[]], ['f',[]], ['AABB',[170,187]],
    ['ab cd',[171]], ['ab\ncd',[171]], ['',[]]
  ]) assert.deepEqual(app.hexPreview(text),expected);
});
